import{K as o,a as s,c,b as t,k as l,q as d,ac as i}from"./chunks/framework.BSuaGltH.js";const f=JSON.parse('{"title":"Access 入门、表设计与数据关系","description":"用客户和订单建立 Access 数据库，选择字段类型、主键和外键，维护一对多关系与参照完整性，区分数据库和 Excel 表格。","frontmatter":{"title":"Access 入门、表设计与数据关系","description":"用客户和订单建立 Access 数据库，选择字段类型、主键和外键，维护一对多关系与参照完整性，区分数据库和 Excel 表格。","showdocs":{"topics":[{"id":"office","title":"Office","link":"/topics/office/"}],"kind":"使用指南","scope":"general","audience":"general","group":"工程与工具","seriesTitle":"Office · Access 数据库入门","summary":"用客户和订单建立 Access 数据库，选择字段类型、主键和外键，维护一对多关系与参照完整性，区分数据库和 Excel 表格。","status":"active","related":[{"title":"Excel 实战：建立可刷新、可核对的月报","link":"/tools/office/excel/project","kind":"实践案例","scope":"general","audience":"general"},{"title":"Office 常见问题排查与交付检查表","link":"/tools/office/collaboration/troubleshooting","kind":"故障排查","scope":"general","audience":"general"},{"title":"Office 常用快捷键、选择与粘贴技巧","link":"/tools/office/start/shortcuts","kind":"参考资料","scope":"general","audience":"general"},{"title":"Office 综合实战：从数据到报告、演示和会议","link":"/tools/office/collaboration/workflow","kind":"实践案例","scope":"general","audience":"general"},{"title":"Word 实战：制作可维护的项目报告","link":"/tools/office/word/report","kind":"实践案例","scope":"general","audience":"general"}],"prev":false,"next":{"text":"Access 查询、窗体、报表与维护","link":"/tools/office/access/forms"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":false,"next":{"text":"Access 查询、窗体、报表与维护","link":"/tools/office/access/forms"}},"headers":[],"relativePath":"tools/office/access/data.md","filePath":"tools/office/access/data.md"}'),n={name:"tools/office/access/data.md"},m=Object.assign(n,{setup(h){const a={path:"/tools/office/access/data",app:"Access",title:"建立有约束的客户与订单关系",steps:[{tab:"创建",command:"表设计",setting:"Customers：自动编号主键；Orders：客户编号为长整型",anchor:"walkthrough-1"},{tab:"数据库工具",command:"关系",setting:"Customers.CustomerID → Orders.CustomerID；启用参照完整性",anchor:"walkthrough-2"},{tab:"开始",command:"视图",setting:"切到数据表视图；三笔金额：100 / 200 / 300",anchor:"walkthrough-3"}]};return(u,e)=>{const r=o("OfficeGuide");return s(),c("div",null,[e[0]||(e[0]=t("h1",{id:"access-入门、表设计与数据关系",tabindex:"-1"},[l("Access 入门、表设计与数据关系 "),t("a",{class:"header-anchor",href:"#access-入门、表设计与数据关系","aria-label":'Permalink to "Access 入门、表设计与数据关系"'},"​")],-1)),e[1]||(e[1]=t("p",null,"Access 适合学习关系数据、表单录入和固定报表，也可用于经过评估的小型桌面业务系统。本篇以 Windows 桌面版为例；Access 不包含在所有 Office 套件中，也不是 Mac 或浏览器中的同等桌面应用。",-1)),d(r,{guide:a}),e[2]||(e[2]=i('<h2 id="choose" tabindex="-1">何时从 Excel 转向数据库 <a class="header-anchor" href="#choose" aria-label="Permalink to &quot;何时从 Excel 转向数据库 {#choose}&quot;">​</a></h2><p>Excel 适合计算、分析和灵活试算；当相同客户信息在大量订单行中重复、需要统一录入界面和明确关系时，可考虑关系数据库。不是数据一多就必须用 Access，长期多人写入、高可用或互联网服务需要进一步评估其他数据库方案。</p><p>一个 Access 文件中可以包含表、查询、窗体、报表、宏和模块。表存数据，查询筛选和组合数据，窗体帮助输入，报表负责输出。不能把不同用途都塞进同一张巨大表里。<a href="https://support.microsoft.com/en-us/access/introduction-to-tables" target="_blank" rel="noopener noreferrer">微软表与关系介绍</a></p><h2 id="tables" tabindex="-1">创建客户与订单表 <a class="header-anchor" href="#tables" aria-label="Permalink to &quot;创建客户与订单表 {#tables}&quot;">​</a></h2><p>新建空白数据库 <code>订单练习.accdb</code>，在表设计视图建立：</p><table tabindex="0"><thead><tr><th>表</th><th>字段</th><th>类型与用途</th></tr></thead><tbody><tr><td>Customers</td><td>CustomerID</td><td>自动编号，主键</td></tr><tr><td>Customers</td><td>CustomerName</td><td>短文本，必填</td></tr><tr><td>Customers</td><td>Phone</td><td>短文本，保留前导零和符号</td></tr><tr><td>Orders</td><td>OrderID</td><td>自动编号，主键</td></tr><tr><td>Orders</td><td>CustomerID</td><td>数字，字段大小为长整型，引用客户</td></tr><tr><td>Orders</td><td>OrderDate</td><td>日期/时间</td></tr><tr><td>Orders</td><td>Amount</td><td>货币</td></tr><tr><td>Orders</td><td>Status</td><td>短文本</td></tr></tbody></table><p>金额字段是否允许负数取决于退货等业务规则，本练习只录入非负订单。电话、证件和编码通常应按文本保存，不因内容都是数字就设为数值。主键用于唯一识别记录，客户名称可能重复，不适合直接当作本练习的主键。</p><h2 id="relationships" tabindex="-1">建立一对多关系 <a class="header-anchor" href="#relationships" aria-label="Permalink to &quot;建立一对多关系 {#relationships}&quot;">​</a></h2><p>先录入两位虚构客户并记下实际生成的 CustomerID，再在订单中引用对应 ID。打开“数据库工具 → 关系”，添加两张表，把 Customers.CustomerID 拖到 Orders.CustomerID，检查连接字段类型和方向，按练习需要启用参照完整性。</p><p>参照完整性可防止订单引用不存在的客户。启用前已有的孤立记录会导致失败，应先核对数据。级联删除会把相关记录一起删除，不能为了省事随意勾选；订单需要保留历史时，通常应采用停用客户等业务处理方式，而不是直接删除。</p><h2 id="import" tabindex="-1">导入 Excel 数据 <a class="header-anchor" href="#import" aria-label="Permalink to &quot;导入 Excel 数据 {#import}&quot;">​</a></h2><p>从“外部数据”选择相应 Excel 来源，根据需要导入为新表、追加或建立链接。导入是一次复制，链接依赖外部源；列名、类型、主键与重复值必须在向导中检查，完成后比对行数和金额。</p><p>导入失败时查看错误表或提示，重点检查字段类型、长度、日期格式和唯一键冲突。不要为消除错误把所有列都改成长文本，否则只是把问题推迟到查询和计算阶段。</p><h2 id="practice" tabindex="-1">练习与验收 <a class="header-anchor" href="#practice" aria-label="Permalink to &quot;练习与验收 {#practice}&quot;">​</a></h2><p>为两位客户各建立订单，总共三笔金额 100、200、300，总额 600。查询客户订单时应能正确显示每笔归属；尝试输入一个不存在的 CustomerID，在参照完整性生效时应被阻止。不要删除练习主表来测试正式数据，先保留数据库副本。</p><p>下一篇使用<a href="/tools/office/access/forms">查询、窗体与报表</a>完成录入和输出。</p><h2 id="walkthrough" tabindex="-1">图示跟做：建立有约束的客户与订单关系 <a class="header-anchor" href="#walkthrough" aria-label="Permalink to &quot;图示跟做：建立有约束的客户与订单关系 {#walkthrough}&quot;">​</a></h2><p>按上方图示切换三个关键步骤；下面保留完整操作和检查结果，便于跟做与回查。请先使用练习副本。</p><h3 id="walkthrough-1" tabindex="-1">第 1 步：按字段用途建两张表 <a class="header-anchor" href="#walkthrough-1" aria-label="Permalink to &quot;第 1 步：按字段用途建两张表 {#walkthrough-1}&quot;">​</a></h3><p><strong>定位：创建 → 表设计。</strong></p><p>创建练习 accdb，在表设计中按正文建立 Customers 和 Orders。CustomerID 在客户表为自动编号主键，在订单表为数字且字段大小是长整型。电话用短文本，金额用货币。保存两表后录入两位虚构客户，记下实际生成的编号，不假设一定从 1 开始。</p><h3 id="walkthrough-2" tabindex="-1">第 2 步：建立一对多并检查方向 <a class="header-anchor" href="#walkthrough-2" aria-label="Permalink to &quot;第 2 步：建立一对多并检查方向 {#walkthrough-2}&quot;">​</a></h3><p><strong>定位：数据库工具 → 关系。</strong></p><p>打开关系窗口，加入两张表，将客户主键拖到订单的 CustomerID。确认两端字段与类型，启用参照完整性并创建关系，观察一端和多端标记。不要为了消除提示随意勾级联删除；已有孤立订单要先修正，关系才可能成功建立。</p><h3 id="walkthrough-3" tabindex="-1">第 3 步：用有效与无效记录验收 <a class="header-anchor" href="#walkthrough-3" aria-label="Permalink to &quot;第 3 步：用有效与无效记录验收 {#walkthrough-3}&quot;">​</a></h3><p><strong>定位：开始 → 视图。</strong></p><p>在订单表输入三条练习记录，金额为 100、200、300，客户编号引用已存在的两位客户，总额为 600。再尝试不存在的客户编号，应被完整性约束阻止；取消这条失败输入。关闭并重开数据库，确认有效三条记录仍存在。</p><h3 id="walkthrough-check" tabindex="-1">没有得到预期结果时 <a class="header-anchor" href="#walkthrough-check" aria-label="Permalink to &quot;没有得到预期结果时 {#walkthrough-check}&quot;">​</a></h3><p>能画出关系线不等于已启用约束。验收必须包括无效外键被阻止；字段类型不匹配时先修正模型，不要放弃完整性后继续录入。</p>',29))])}}});export{f as __pageData,m as default};
